document.addEventListener('change',e=>{if(e.target.id==='availability'){availability=e.target.value;render();}if(e.target.id==='include-archive'){includeArchive=e.target.checked;render();}if(e.target.matches('[data-day]')){const day=Number(e.target.dataset.day);const completed=planCompleted();state.planDays=state.planDays||{};state.planDays[currentDomain]=e.target.checked?[...new Set([...completed,day])]:completed.filter(x=>x!==day);persist();render();}});
document.addEventListener('input',e=>{if(e.target.id==='code-draft'){const item=data.find(i=>i.id===route().id);state.drafts[draftKey(item)]=e.target.value;persist();}});
async function copyText(text,button){let ok=false;try{await navigator.clipboard.writeText(text);ok=true;}catch{const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.left='-9999px';document.body.append(field);field.select();ok=document.execCommand('copy');field.remove();}if(ok){const before=button.textContent;button.textContent='Copied ✓';setTimeout(()=>button.textContent=before,1600);}else toast('Select the text and copy it with your keyboard.');}
